import numpy as np
from sklearn.mixture import GaussianMixture

def gmm_threshold(x):
 x=np.asarray(x,float); z=np.log1p(np.clip(x,0,None)); z=z-z.mean();
 gm=GaussianMixture(2,n_init=10,random_state=1).fit(z.reshape(-1,1)); mu=gm.means_.ravel(); sd=np.sqrt(gm.covariances_.ravel()); order=np.argsort(mu); lo,hi=mu[order[0]],mu[order[1]]
 # intersection weighted by component weights
 w=gm.weights_[order]; p1=lo+w[0]/w.sum()*np.exp(-.5*((lo-hi)/sd[0])**2); p2=hi+w[1]/w.sum()*np.exp(-.5*((hi-lo)/sd[1])**2); cross=p1+p2
 return float(np.expm1(np.clip(cross, -20,30)))
for name in ['PBMC_D617.fcs','PBMC_D685.fcs','PBMC_D735.fcs','PBMC_D829.fcs','PBMC_D858.fcs','PBMC_D960.fcs','fmo_HLADR.fcs','fmo_HLADR_rerun.fcs','ctrl_unstained.fcs']:
